{"revision":4,"files":[{"path":"slugify.mjs","hash":"bd832a8618a7b2695b32c5dc29ab76923d9eccc8a661212e787308b452518064","content":"export function slugify(value) {
  if (typeof value !== 'string') {
    throw new TypeError('slugify requires a string');
  }

  return value
    .normalize('NFKD')
    .replace(/\p{M}+/gu, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}
